describe('Google Account Connection to User Profile', () => {
  beforeEach(() => {
    cy.visit('/user-profile');
  });

  it('should successfully connect Google account to user profile', () => {
    // Verify initial state: no Google account connected
    cy.get('[data-testid="profile-name"]').should('contain', 'No account connected');
    cy.get('[data-testid="profile-email"]').should('contain', 'No email');

    // Intercept the Google OAuth API call
    cy.intercept('POST', '/api/auth/google/login').as('googleLogin');

    // Click the Google account button
    cy.get('[data-testid="google-account-button"]').click();

    // Verify modal appears
    cy.get('[data-testid="google-modal"]').should('be.visible');

    // Fill in Google OAuth form
    cy.get('[data-testid="google-email-input"]').type('user@example.com');
    cy.get('[data-testid="google-password-input"]').type('password123');

    // Click the login button
    cy.get('[data-testid="google-login-button"]').click();

    // Wait for API response
    cy.wait('@googleLogin');

    // Verify successful connection
    cy.get('[data-testid="profile-name"]').should('contain', 'User@example.com');
    cy.get('[data-testid="profile-email"]').should('contain', 'user@example.com');
    cy.get('[data-testid="profile-connected-status"]').should('contain', 'Connected');

    // Verify profile is updated
    cy.get('[data-testid="profile-avatar"]').should('be.visible');
    cy.get('[data-testid="profile-avatar"]').should('have.attr', 'src');
  });

  it('should handle failed Google account connection', () => {
    // Intercept failed Google OAuth API call
    cy.intercept('POST', '/api/auth/google/login', {
      statusCode: 401,
      body: { error: 'Unauthorized', error_description: 'Invalid credentials' }
    }).as('googleLoginFailed');

    // Click the Google account button
    cy.get('[data-testid="google-account-button"]').click();

    // Verify modal appears
    cy.get('[data-testid="google-modal"]').should('be.visible');

    // Fill in Google OAuth form
    cy.get('[data-testid="google-email-input"]').type('user@example.com');
    cy.get('[data-testid="google-password-input"]').type('password123');

    // Click the login button
    cy.get('[data-testid="google-login-button"]').click();

    // Wait for failed API response
    cy.wait('@googleLoginFailed');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to connect');

    // Verify profile remains unchanged
    cy.get('[data-testid="profile-name"]').should('contain', 'No account connected');
    cy.get('[data-testid="profile-email"]').should('not.exist');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });
});
